const drums = stack(
  s("bd*4"),
  s("hh*8").gain("[0.25 0.45]*4"),
  s("[~ oh]*4").gain(0.35),
  s("~ cp ~ cp").gain(0.6),
  s("rim(3,8,2)").gain(0.3),
).bank("RolandTR909").swingBy(1/6, 4)
const bass = note("<[~ c2 ~ c2 ~ c2 ~ eb2] [~ c2 ~ c2 ~ g1 ~ bb1]>").s("sawtooth")
  .lpf(700).decay(0.15).sustain(0).gain(0.5)
